#!/usr/bin/env node
/**
 * Automated CSS Bundler & Inliner
 * Concatenates modular CSS files into a single, self-contained styles.css with zero @import statements.
 * Created by Rajdip Ghosh (https://github.com/RajdipGhosh99).
 */

const fs = require('fs');
const path = require('path');

const STYLES_DIR = path.resolve(__dirname, '../src/styles');
const OUTPUT_FILE = path.join(STYLES_DIR, 'styles.css');

const CSS_FILES = [
  path.join(STYLES_DIR, 'base.css'),
  path.join(STYLES_DIR, 'badge.css'),
  path.join(STYLES_DIR, 'popover.css'),
  path.join(STYLES_DIR, 'hud.css'),
];

// Add all portal css files
const portalsDir = path.join(STYLES_DIR, 'portals');
if (fs.existsSync(portalsDir)) {
  const portalFiles = fs.readdirSync(portalsDir)
    .filter(f => f.endsWith('.css'))
    .map(f => path.join(portalsDir, f));
  CSS_FILES.push(...portalFiles);
}

let bundledContent = `/**\n * Live Train Delay Tracker - Standalone Inlined Stylesheet\n * Auto-generated by scripts/bundle-css.js. Do not edit directly.\n * Created by Rajdip Ghosh (https://github.com/RajdipGhosh99).\n */\n\n`;

for (const file of CSS_FILES) {
  if (fs.existsSync(file)) {
    const content = fs.readFileSync(file, 'utf8');
    // Strip any @import statements
    const cleaned = content.replace(/@import\s+[^;]+;\s*/g, '');
    bundledContent += `/* === ${path.basename(file)} === */\n${cleaned}\n\n`;
  } else {
    console.warn(`[bundle-css] Warning: File not found: ${file}`);
  }
}

fs.writeFileSync(OUTPUT_FILE, bundledContent.trim() + '\n', 'utf8');
console.log(`✅ [bundle-css] Inlined CSS bundle written to src/styles/styles.css (${bundledContent.length} bytes)`);
